import { readFile } from 'node:fs/promises';
import vm from 'node:vm';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const html = await readFile(path.join(root, 'bundle.html'), 'utf8');
const scripts = [...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/gi)].map(match => match[1]);

if (!html.includes('Generated by npm run build')) throw new Error('bundle.html is missing its generated-file marker.');
if (/<script\b[^>]*\bsrc=/i.test(html)) throw new Error('bundle.html still contains an external script.');
if (/<link\b[^>]*\brel=["']stylesheet["']/i.test(html)) {
  throw new Error('bundle.html still contains an external stylesheet.');
}
if (scripts.length === 0) throw new Error('bundle.html contains no executable scripts.');
scripts.forEach((source, index) => new vm.Script(source, { filename: `bundle-script-${index + 1}.js` }));

const bootRegistrations = (html.match(/addEventListener\(['"]DOMContentLoaded['"],\s*boot\)/g) ?? []).length;
if (bootRegistrations !== 1) throw new Error(`Expected one boot registration, found ${bootRegistrations}.`);

console.log(`Verified ${scripts.length} bundle scripts and one application boot registration.`);
